pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, secure, turn-based PvP Tic Tac Toe game.
 * @dev Implements PULL-OVER-PUSH payments, packed storage, and custom errors.
 *      Uses a 3x3 grid where cells are stored in a single uint32 bitmap.
 *      Adheres to Strict Checks-Effects-Interactions pattern.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // CUSTOM ERRORS
    // ═══════════════════════════════════════════════════════════════

    error InvalidStake();
    error GameDoesNotExist();
    error GameNotJoinable();
    error GameNotActive();
    error WrongStake(uint256 expected, uint256 provided);
    error NotYourTurn();
    error InvalidMove(uint8 col, uint8 row);
    error CellOccupied();
    error TransferFailed();
    error NoWinningsToWithdraw();
    error TimeoutNotReached(uint256 currentTime, uint256 deadline);
    error NotAPlayer();
    error SelfPlayNotAllowed();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event GameCreated(uint256 indexed gameId, address indexed player1, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed player2);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 col, uint8 row, uint8 turnCount);
    event GameEnded(uint256 indexed gameId, address indexed winner, uint256 prize);
    event GameDrawDeclared(uint256 indexed gameId, uint256 refundAmount);
    event Withdrawal(address indexed player, uint256 amount);
    event TreasuryFunded(address indexed sender, uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    // Constants
    uint256 public constant MIN_STAKE = 0.001 ether;
    uint32 public constant TURN_TIMEOUT = 1 hours;

    // Status Enum
    enum GameStatus { NON_EXISTENT, WAITING, ACTIVE, COMPLETED }

    // Packed Game Struct (Fits in 2 Storage Slots)
    struct Game {
        // Slot 0 (256 bits)
        address player1;      // 160 bits
        uint96 stake;         // 96 bits (Max ~79 billion ETH)

        // Slot 1 (240 bits used)
        address player2;      // 160 bits
        uint32 lastAction;    // 32 bits (Timestamp)
        uint32 board;         // 32 bits (Stores 9 cells x 2 bits = 18 bits needed)
        uint8 turnCount;      // 8 bits
        GameStatus status;    // 8 bits
    }

    // State
    uint256 public gameIdCounter;
    mapping(uint256 => Game) public games;
    mapping(address => uint256) public pendingWithdrawals;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        // Empty as required
    }

    // ═══════════════════════════════════════════════════════════════
    // EXTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Create a new game with a staked amount
    /// @return gameId The ID of the created game
    function createGame() external payable returns (uint256 gameId) {
        if (msg.value < MIN_STAKE) revert InvalidStake();

        // Use unchecked for global counter (safe from overflow)
        unchecked {
            gameId = ++gameIdCounter;
        }

        Game storage newGame = games[gameId];
        newGame.player1 = msg.sender;
        newGame.stake = uint96(msg.value); // Safe cast due to total ETH supply limits
        newGame.status = GameStatus.WAITING;
        newGame.lastAction = uint32(block.timestamp);

        emit GameCreated(gameId, msg.sender, msg.value);
    }

    /// @notice Join an existing waiting game
    /// @param _gameId The ID of the game to join
    function joinGame(uint256 _gameId) external payable {
        Game storage g = games[_gameId];

        if (g.status != GameStatus.WAITING) revert GameNotJoinable();
        if (msg.value != g.stake) revert WrongStake(g.stake, msg.value);
        if (msg.sender == g.player1) revert SelfPlayNotAllowed();

        g.player2 = msg.sender;
        g.status = GameStatus.ACTIVE;
        g.lastAction = uint32(block.timestamp);

        emit GameJoined(_gameId, msg.sender);
    }

    /// @notice Make a move on the board
    /// @param _gameId The ID of the game
    /// @param _col Column index (0-2)
    /// @param _row Row index (0-2)
    function makeMove(uint256 _gameId, uint8 _col, uint8 _row) external nonReentrant {
        // 1. INPUT VALIDATION
        if (_col > 2 || _row > 2) revert InvalidMove(_col, _row);

        Game storage g = games[_gameId];

        // Cache storage reads to stack for gas optimization
        GameStatus currentStatus = g.status;
        address p1 = g.player1;
        address p2 = g.player2;
        uint32 board = g.board;
        uint8 turns = g.turnCount;

        // 2. STATE CHECKS
        if (currentStatus != GameStatus.ACTIVE) revert GameNotActive();

        // Determine turn: Even turns (0,2,4..) = Player 1, Odd turns = Player 2
        bool isP1Turn = (turns % 2 == 0);
        address currentPlayer = isP1Turn ? p1 : p2;
        uint8 playerValue = isP1Turn ? 1 : 2; // 1 for P1, 2 for P2 in bitmap

        if (msg.sender != currentPlayer) revert NotYourTurn();

        // Calculate cell bit position: (row * 3 + col) * 2
        uint256 shift = (_row * 3 + _col) * 2;

        // Check if cell is empty (bits are 00 at position)
        if ((board >> shift) & 3 != 0) revert CellOccupied();

        // 3. EFFECTS (Update State)

        // Update board: OR operation to set bits
        board = board | (uint32(playerValue) << shift);
        g.board = board; 

        // Increment turn count safely
        unchecked {
            ++turns;
        }
        g.turnCount = turns;
        g.lastAction = uint32(block.timestamp);

        emit MoveMade(_gameId, msg.sender, _col, _row, turns);

        // Check Win Condition
        if (_checkWin(board, playerValue)) {
            _endGame(_gameId, g, currentPlayer, p1, p2, false);
            return;
        }

        // Check Draw Condition (9 moves made with no winner)
        if (turns == 9) {
            _endGame(_gameId, g, address(0), p1, p2, true);
            return;
        }
    }

    /// @notice Claim victory if opponent timed out
    /// @param _gameId The ID of the game
    function claimTimeout(uint256 _gameId) external nonReentrant {
        Game storage g = games[_gameId];

        if (g.status != GameStatus.ACTIVE) revert GameNotActive();

        // Check timeout
        uint256 deadline = uint256(g.lastAction) + TURN_TIMEOUT;
        if (block.timestamp < deadline) revert TimeoutNotReached(block.timestamp, deadline);

        // Identify winner based on who's turn it currently is (the person who failed to move)
        // If turnCount is Even (P1's turn), P1 timed out -> P2 wins.
        // If turnCount is Odd (P2's turn), P2 timed out -> P1 wins.

        address winner;
        address p1 = g.player1;
        address p2 = g.player2;

        if (g.turnCount % 2 == 0) {
            winner = p2;
        } else {
            winner = p1;
        }

        // Verify caller is the winner (security check)
        if (msg.sender != winner) revert NotAPlayer();

        _endGame(_gameId, g, winner, p1, p2, false);
    }

    /// @notice Withdraw pending winnings (Pull-Over-Push)
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NoWinningsToWithdraw();

        // CEI: Update state before interaction
        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(msg.sender, amount);
    }

    /// @notice Allow treasury funding
    receive() external payable {
        emit TreasuryFunded(msg.sender, msg.value);
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL LOGIC
    // ═══════════════════════════════════════════════════════════════

    /// @dev Handles game resolution, funds distribution, and cleanup
    function _endGame(
        uint256 _gameId, 
        Game storage _game, 
        address _winner, 
        address _p1, 
        address _p2, 
        bool _isDraw
    ) internal {
        // Update status for reentrancy safety (though logic ends here)
        _game.status = GameStatus.COMPLETED;

        uint256 totalPot = uint256(_game.stake) * 2;

        if (_isDraw) {
            // Split pot for draw
            uint256 half = totalPot / 2;
            pendingWithdrawals[_p1] += half;
            pendingWithdrawals[_p2] += half;
            emit GameDrawDeclared(_gameId, half);
        } else {
            // Winner takes all
            pendingWithdrawals[_winner] += totalPot;
            emit GameEnded(_gameId, _winner, totalPot);
        }

        // GAS OPTIMIZATION: Delete the game struct to refund gas.
        // History is preserved via emitted events.
        delete games[_gameId];
    }

    /// @dev Checks if the board contains a winning line for the player
    /// @param _board The uint32 bitmap of the board
    /// @param _pVal The player value (1 or 2)
    /// @return True if player has won
    function _checkWin(uint32 _board, uint8 _pVal) internal pure returns (bool) {
        // Winning Logic: Check all 8 possible lines.
        // A line is valid if all 3 cells in the line equal _pVal.

        // Rows
        if (_checkLine(_board, 0, 1, 2, _pVal)) return true;
        if (_checkLine(_board, 3, 4, 5, _pVal)) return true;
        if (_checkLine(_board, 6, 7, 8, _pVal)) return true;

        // Cols
        if (_checkLine(_board, 0, 3, 6, _pVal)) return true;
        if (_checkLine(_board, 1, 4, 7, _pVal)) return true;
        if (_checkLine(_board, 2, 5, 8, _pVal)) return true;

        // Diagonals
        if (_checkLine(_board, 0, 4, 8, _pVal)) return true;
        if (_checkLine(_board, 2, 4, 6, _pVal)) return true;

        return false;
    }

    /// @dev Helper to check 3 specific cells
    function _checkLine(uint32 _board, uint256 a, uint256 b, uint256 c, uint8 val) private pure returns (bool) {
        // Retrieve 2-bit value at index: (board >> (index * 2)) & 3
        return (((_board >> (a * 2)) & 3) == val) &&
               (((_board >> (b * 2)) & 3) == val) &&
               (((_board >> (c * 2)) & 3) == val);
    }
}

